  1	package com.fream.back.domain.shipment.entity;
  2	
  3	import com.fream.back.domain.order.entity.Order;
  4	import com.fream.back.global.entity.BaseTimeEntity;
  5	import jakarta.persistence.*;
  6	import lombok.AllArgsConstructor;
  7	import lombok.Builder;
  8	import lombok.Getter;
  9	import lombok.NoArgsConstructor;
 10	
 11	@Entity
 12	@Getter
 13	@NoArgsConstructor
 14	@AllArgsConstructor
 15	@Builder
 16	public class OrderShipment extends BaseTimeEntity {
 17	
 18	    @Id
 19	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 20	    private Long id;
 21	
 22	    @OneToOne(fetch = FetchType.LAZY)
 23	    @JoinColumn(name = "order_id", nullable = false)
 24	    private Order order;
 25	
 26	    private String receiverName; // 수령인 이름
 27	    private String receiverPhone; // 수령인 전화번호
 28	    private String postalCode; // 우편번호
 29	    private String address; // 주소
 30	    private String courier; // 택배사 이름
 31	    private String trackingNumber; // 송장 번호
 32	
 33	    @Enumerated(EnumType.STRING)
 34	    private ShipmentStatus status;
 35	
 36	
 37	    public void assignOrder(Order order) {
 38	        this.order = order;
 39	    }
 40	
 41	    public void updateTrackingInfo(String courier, String trackingNumber) {
 42	        this.courier = courier;
 43	        this.trackingNumber = trackingNumber;
 44	        this.status = ShipmentStatus.IN_TRANSIT;
 45	    }
 46	
 47	    public void updateStatus(ShipmentStatus newStatus) {
 48	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
 49	            this.status = newStatus;
 50	        } else {
 51	            throw new IllegalStateException(
 52	                    "Cannot transition from " + this.status + " to " + newStatus
 53	            );
 54	        }
 55	    }
 56	}
 57	package com.fream.back.domain.shipment.entity;
 58	
 59	public enum ShipmentStatus {
 60	    PENDING {
 61	        @Override
 62	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 63	            return nextStatus == SHIPPED || nextStatus == CANCELED;
 64	        }
 65	    },
 66	    SHIPPED {
 67	        @Override
 68	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 69	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
 70	        }
 71	    },
 72	    IN_TRANSIT {
 73	        @Override
 74	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 75	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
 76	                    || nextStatus == DELIVERED;
 77	        }
 78	    },
 79	    OUT_FOR_DELIVERY {
 80	        @Override
 81	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 82	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
 83	        }
 84	    },
 85	    DELIVERED {
 86	        @Override
 87	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 88	            return false; // 배송 완료 이후로는 상태 전환 없음
 89	        }
 90	    },
 91	    RETURNED {
 92	        @Override
 93	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 94	            return nextStatus == CANCELED;
 95	        }
 96	    },
 97	    CANCELED {
 98	        @Override
 99	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
100	            return false; // 취소 이후 상태 전환 없음
101	        }
102	    },
103	    DELAYED {
104	        @Override
105	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
106	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
107	        }
108	    },
109	    FAILED_DELIVERY {
110	        @Override
111	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
112	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
113	        }
114	    };
115	
116	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
117	}

