   280	    /**
   281	     * 전체 배송 상태를 주기적으로 업데이트합니다.
   282	     */
   283	    @Transactional
   284	    public void updateShipmentStatuses() {
   285	        log.info("전체 배송 상태 업데이트 시작");
   286	
   287	        // 1. IN_TRANSIT 또는 OUT_FOR_DELIVERY 상태의 OrderShipment 조회
   288	        List<OrderShipment> shipments = orderShipmentRepository.findByStatusIn(
   289	                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
   290	        );
   291	
   292	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
   293	
   294	        int successCount = 0;
   295	        int errorCount = 0;
   296	
   297	        for (OrderShipment shipment : shipments) {
   298	            try {
   299	                String trackingNumber = shipment.getTrackingNumber();
   300	                if (trackingNumber == null || trackingNumber.isBlank()) {
   301	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
   302	                    errorCount++;
   303	                    continue;
   304	                }
   305	
   306	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
   307	                        shipment.getId(), trackingNumber);
   308	
   309	                // 2. CJ대한통운에서 현재 배송 상태 추출
   310	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
   311	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
   312	
   313	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
   314	                        shipment.getId(), currentStatus, newStatus);
   315	
   316	                // 현재 상태와 동일한 경우 중복 처리 방지
   317	                if (shipment.getStatus() == newStatus) {
   318	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   319	                            shipment.getId(), newStatus);
   320	                    successCount++;
   321	                    continue;
   322	                }
   323	
   324	                // 3. 배송 상태가 DELIVERED인 경우 Order와 Shipment 상태 업데이트
   325	                if (newStatus == ShipmentStatus.DELIVERED) {
   326	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
   327	
   328	                    shipment.updateStatus(newStatus);
   329	                    Order order = shipment.getOrder();
   330	                    order.updateStatus(OrderStatus.COMPLETED);
   331	
   332	                    // 배송 완료 알림 전송
   333	                    User buyer = order.getUser();
   334	                    notificationCommandService.createNotification(
   335	                            buyer.getId(),
   336	                            NotificationCategory.SHOPPING,
   337	                            NotificationType.BID,
   338	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
   339	                    );
   340	
   341	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
   342	                            buyer.getId(), order.getId());
   343	
   344	                } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY &&
   345	                        shipment.getStatus() != ShipmentStatus.OUT_FOR_DELIVERY) {
   346	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
   347	                    shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
   348	
   349	                } else {
   350	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
   351	                            shipment.getId(), newStatus);
   352	                    shipment.updateStatus(newStatus);
   353	                }
   354	
   355	                orderShipmentRepository.save(shipment);
   356	                successCount++;
   357	
   358	            } catch (Exception e) {
   359	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
   360	                        shipment.getId(), e.getMessage(), e);
   361	                errorCount++;
   362	            }
   363	        }
   364	
   365	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
   366	    }
